            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "I say the whole earth and all the stars in the sky are for religion’s sake.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "None has begun to think how divine he himself is and how certain the future is.", Author = "Walt Whitman" },
