            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "Each of us inevitable;\nEach of us limitless—each of us with his or her right upon the earth.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "The great city is that which has the greatest man or woman.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "In this broad earth of ours,\nAmid the measureless grossness and the slag,\nEnclosed and safe within its central heart,\nNestles the seed perfection.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "All, all for immortality,\nLove like the light silently wrapping all.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "Youth, large, lusty, loving—Youth, full of grace, force, fascination!\nDo you know that Old Age may come after you, with equal grace, force, fascination?", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "Roaming in thought over the Universe, I saw the little that is Good steadily hastening towards immortality,\nAnd the vast that is evil I saw hastening to merge itself and become lost and dead.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "Thunder on! Stride on! Democracy. Strike with vengeful stroke!", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "Over all the sky—the sky! far, far out of reach, studded with the eternal stars.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "Give me the splendid silent sun, with all his beams full-dazzling!", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "Lo! the moon ascending!\nUp from the East, the silvery round moon;\nBeautiful over the house-tops, ghastly, phantom moon;\nImmense and silent moon.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "Beautiful that war and all its deeds of carnage, must in time be utterly lost;\nThat the hands of the sisters Death and Night incessantly softly wash again and ever again, this soiled world.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "When lilacs last in the door-yard bloomed,\nAnd the great star early drooped in the western sky in the night,\nI mourned, and yet shall mourn with ever-returning spring.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "Come lovely and soothing death,\nUndulate round the world, serenely arriving, arriving,\nIn the day, in the night, to all, to each,\nSooner or later, delicate death.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "Praised be the fathomless universe\nFor life and joy and for objects and knowledge curious;\nAnd for love, sweet love—But praise! O praise and praise\nFor the sure-enwinding arms of cool-enfolding Death.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "Liberty is to be subserved, whatever occurs.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "Peace is always beautiful.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "What do you suppose will satisfy the soul except to walk free and own no superior?", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "To me every hour of the light and dark is a miracle,\nEvery cubic inch of space is a miracle.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "I was thinking the day most splendid, till I saw what the not-day exhibited;\nI was thinking this globe enough, till there sprang out so noiseless around me myriads of other globes.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "I swear I think there is nothing but immortality!", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "The paths to the house I seek to make,\nBut leave to those to come the house itself.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "Society waits unformed and is between things ended and things begun.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "Now obey thy cherished secret wish,\nEmbrace thy friends—leave all in order;\nTo port and hawser's tie no more returning,\nDepart upon thy endless cruise, old Sailor!", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "I announce the great individual, fluid as Nature, chaste, affectionate, compassionate, fully armed;\nI announce a life that shall be copious, vehement, spiritual, bold,\nAnd I announce an end that shall lightly and joyfully meet its translation.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "Incompossible, adj. Unable to exist if something else exists. Two things are incompossible when the world of being has scope enough for one of them, but not enough for both—as Walt Whitman's poetry and God's mercy to man.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "Whitman...a man full-blooded and brotherly, unselfconscious in his democracy and genuinely at ease with all kinds and classes.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "I give you joy of your free and brave thought. I have great joy in it. I find incomparable things said incomparably well, as they must be.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "I always knew in my heart Walt Whitman’s mind to be more like my own than any other man’s living.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "One Whitman is miracle enough, and when he comes again it will be the end of the world.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "Whitman to me is the most fascinating of American poets.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "Whitman started to write the great poetry from scratch after he had written all that junk for newspapers, the sentimental lyrical poems. All of a sudden he wrote Leaves of Grass.", Author = "Walt Whitman" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Walt_Whitman", Text = "I would think Walt Whitman probably had more influence on my whole poetic thinking than anybody, but I never dreamed of trying to write in the Whitman manner.", Author = "Walt Whitman" },
